<script setup lang="ts">
import { formatSettlementAmountMinor } from '../../../../domain/settlement'
const route = useRoute(); const router = useRouter(); const groupsStore = useGroupsStore(); const { remove } = useSettlements()
const groupId = computed(() => String(route.params.id)); const settlementId = computed(() => String(route.params.settlementId))
const group = computed(() => groupsStore.findGroup(groupId.value)); const settlement = computed(() => groupsStore.settlements.find(item => item.id === settlementId.value && item.groupId === groupId.value))
const participants = computed(() => new Map(groupsStore.participantsForGroup(groupId.value).map(item => [item.id, item])))
const editing = ref(false); const status = ref(''); const deleteError = ref(''); const deleting = ref(false); const dialog = ref<HTMLDialogElement | null>(null); const deleteTrigger = ref<HTMLButtonElement | null>(null); const cancelDeleteButton = ref<HTMLButtonElement | null>(null); const deleteButton = ref<HTMLButtonElement | null>(null); const heading = ref<HTMLHeadingElement | null>(null)
async function focusHeading() { await nextTick(); heading.value?.focus() }
async function saved() { editing.value = false; status.value = 'Zahlung lokal gespeichert.'; await focusHeading() }
async function startEditing() { editing.value = true; await nextTick(); document.querySelector<HTMLSelectElement>('#settlement-sender')?.focus() }
function askDelete() { status.value = ''; deleteError.value = ''; dialog.value?.showModal(); nextTick(() => cancelDeleteButton.value?.focus()) }
function cancelDelete() { if (deleting.value) return; dialog.value?.close(); nextTick(() => deleteTrigger.value?.focus()) }
async function confirmDelete() {
  if (!settlement.value || deleting.value) return
  status.value = ''; deleting.value = true
  try { await remove(settlement.value); dialog.value?.close(); await router.push(`/groups/${groupId.value}/settlements?deleted=1`) }
  catch { deleteError.value = 'Die Zahlung konnte nicht lokal gelöscht werden.'; deleting.value = false; await nextTick(); deleteButton.value?.focus() }
  finally { deleting.value = false }
}
onMounted(() => { if (route.query.created === '1') void focusHeading() })
</script>
<template><main class="page-shell"><div v-if="group && settlement" class="page-content"><NuxtLink :to="`/groups/${group.id}/settlements`" class="secondary-link -ml-4 mb-3">← Zahlungen</NuxtLink><header class="min-w-0"><p class="break-words text-sm font-semibold tracking-wide text-brand-700">{{ group.name }}</p><h1 ref="heading" tabindex="-1" class="mt-2 text-3xl font-semibold text-brand-900">Zahlung</h1></header><p v-if="route.query.created === '1'" class="mt-5 rounded-lg bg-brand-50 p-3 text-brand-900" role="status">Zahlung lokal gespeichert.</p><GroupSyncStatus :group-id="group.id" class="mt-4" /><p v-if="status" class="mt-4" :class="status.includes('konnte nicht') ? 'error-text' : ''" :role="status.includes('konnte nicht') ? 'alert' : 'status'">{{ status }}</p><SettlementForm v-if="editing" class="mt-6" :group-id="group.id" :settlement="settlement" @saved="saved" /><template v-else><dl class="card mt-6 grid min-w-0 grid-cols-1 gap-4 p-5 sm:grid-cols-2"><div><dt class="text-sm text-gray-600">Betrag</dt><dd class="font-semibold">{{ formatSettlementAmountMinor(settlement.amountMinor) }}</dd></div><div><dt class="text-sm text-gray-600">Datum</dt><dd class="font-semibold">{{ settlement.occurredOn }}</dd></div><div class="min-w-0"><dt class="text-sm text-gray-600">Gezahlt von</dt><dd class="break-words font-semibold">{{ participants.get(settlement.senderParticipantId)?.name }}</dd></div><div class="min-w-0"><dt class="text-sm text-gray-600">Gezahlt an</dt><dd class="break-words font-semibold">{{ participants.get(settlement.receiverParticipantId)?.name }}</dd></div></dl><div v-if="group.status === 'active'" class="mt-5 grid gap-3 sm:grid-cols-2"><button type="button" class="secondary-button" @click="startEditing">Bearbeiten</button><button ref="deleteTrigger" type="button" class="danger-button" @click="askDelete">Zahlung löschen</button></div><p v-else class="card mt-5 p-4">Diese archivierte Gruppe ist schreibgeschützt.</p></template><dialog ref="dialog" role="alertdialog" class="delete-dialog rounded-2xl p-0" aria-labelledby="settlement-delete-title" aria-describedby="settlement-delete-description" :aria-busy="deleting" @cancel.prevent="cancelDelete"><div class="p-5"><h2 id="settlement-delete-title" class="text-xl font-semibold">Zahlung löschen</h2><p id="settlement-delete-description" class="mt-3">Diese Zahlung endgültig löschen?</p><p v-if="deleteError" class="error-text mt-3" role="alert">{{ deleteError }}</p><div class="mt-5 flex flex-wrap gap-2"><button ref="cancelDeleteButton" type="button" class="secondary-button" :disabled="deleting" @click="cancelDelete">Abbrechen</button><button ref="deleteButton" type="button" class="danger-button" :disabled="deleting" @click="confirmDelete">{{ deleting ? 'Wird gelöscht …' : 'Endgültig löschen' }}</button></div></div></dialog></div><div v-else class="page-content"><h1 class="text-3xl font-semibold">Zahlung nicht gefunden</h1><NuxtLink :to="`/groups/${groupId}/settlements`" class="secondary-link mt-5">Zu den Zahlungen</NuxtLink></div></main></template>
